#!/usr/bin/env python3
"""Regenerate docs/TEST_CATALOG.md from the skill's test_cases.json (CI checks it is in sync)."""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
SRC = ROOT / ".claude" / "skills" / "merch-vendor-review" / "references" / "test_cases.json"


def render(data):
    tests = data["tests"]
    lines = [f"# Test catalogue (v{data['version']})", "",
             "Generated by `tools/gen_test_catalog.py` from `test_cases.json`. Do not edit by hand.", "",
             f"{len(tests)} tests. Priority weights: " +
             ", ".join(f"{k}={v}" for k, v in data["priority_weights"].items()) +
             ". **risk** = a No/Open needs an engineering escalation.", "", "## Integration gate", ""]
    for i, g in enumerate(data["gate"], 1):
        ids = ", ".join(g.get("all", []))
        extra = f"; any of {', '.join(g['any'])}" if g.get("any") else ""
        sm = "; valid status map" if g.get("status_map") else ""
        lines.append(f"{i}. {g['item']} ({ids}{extra}{sm})")
    for section in dict.fromkeys(t["section"] for t in tests):
        lines += ["", f"## {section}", "", "| ID | P | Verify | Test | Pass criteria | Platform impact |",
                  "|---|---|---|---|---|---|"]
        for t in (t for t in tests if t["section"] == section):
            flag = " **risk**" if t.get("risk") else ""
            cells = [t["id"] + flag, t["priority"], t["verify"], t["test"], t["pass"], t["platform"]]
            lines.append("| " + " | ".join(c.replace("|", "\\|") for c in cells) + " |")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    out = ROOT / "docs" / "TEST_CATALOG.md"
    out.write_text(render(json.loads(SRC.read_text())))
    print(f"Wrote {out}")
